entries[36040] = { ["name"] = "Teufelsflammenstoß", ["text"] = "260 Mana 30 Meter Reichweite\nWirken in 3 sek.\nLässt eine Flammensäule niedergehen, die alle Feinde im ausgewählten Gebiet verbrennt und ihnen 8 Sek. lang alle 2 Sek. zusätzlichen Schaden zufügt." }
