entries[36074] = { ["name"] = "Gamaschen des schwarzen Sturms", ["text"] = "Wirken in 10 sek.\nReagenzien:\nUnverwüstliches Leder (10), Odem des Windes (8), Geschmeidiger dicker Balg (2), Runenfaden\nGamaschen des schwarzen Sturms\nWird beim Aufheben gebunden\nBeine Leder\n194 Rüstung\n+16 Beweglichkeit\n+30 Ausdauer\nErhöht Eure Trefferwertung um + 10.\nHaltbarkeit 100 / 100\n45" }
