entries[36076] = { ["name"] = "Gamaschen des Drachenschlags", ["text"] = "Wirken in 10 sek.\nReagenzien:\nUnverwüstliches Leder (10), Abgenutzte Drachenschuppe (10), Geschmeidiger dicker Balg (2), Runenfaden\nGamaschen des Drachenschlags\nWird beim Aufheben gebunden\nBeine Kette\n316 Rüstung\n+17 Beweglichkeit\n+18 Ausdauer\nErhöht Eure Trefferwertung um + 10.\nErhöht Eure kritische Trefferwertung um + 12.\nHaltbarkeit 100 / 100\n45" }
