entries[36122] = { ["name"] = "Erdgeschmiedete Gamaschen", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nMithrilbarren (16), Erdenkern (2)\nErdgeschmiedete Gamaschen\nWird beim Aufheben gebunden\nBeine Platte\n475 Rüstung\n+16 Stärke\n+16 Ausdauer\nErhöht Eure kritische Trefferwertung um + 10.\n43 Rüstung\nHaltbarkeit 100 / 100\n47" }
entries[36123] = { ["name"] = "Saat der Verderbnis", ["text"] = "550 Mana 30 Meter Reichweite\nWirken in 2 sek.\nPflanzt dem feindlichen Ziel eine Saat der Verderbnis ein, die im Verlauf von 18 Sek. 2400 Schattenschaden verursacht. Wenn das Ziel insgesamt 2500 Schaden erleidet, detoniert die Saat und fügt allen Feinden im Umkreis von 10 Metern um das Ziel Schattenschaden zu." }
