entries[36868] = { ["name"] = "Schattenblitz", ["text"] = "85 Mana 40 Meter Reichweite\nWirken in 1 sek.\nSchleudert einen Blitz aus dunkler Magie auf einen Feind und verursacht 1800 bis 2200 Schattenschaden." }
entries[36871] = { ["name"] = "Schießen" }
entries[36872] = { ["name"] = "Tödliches Gift", ["text"] = "10 Meter Reichweite\nSofort 30 sek. Abklingzeit\nFügt einem Gegner 15 Sek. lang alle 3 Sek. 324 bis 376 Naturschaden zu." }
entries[36876] = { ["name"] = "Feuerkegel", ["text"] = "10 Meter Reichweite\nSofort\nFügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden 5550 bis 6450 Feuerschaden zu." }
entries[36877] = { ["name"] = "Für immer betäubt", ["text"] = "Unbegrenzte Reichweite\nSofort\nBetäubt einen Feind, sodass er sich 1 Min. lang weder bewegen noch angreifen kann." }
entries[36878] = { ["name"] = "Knochenwüste - Weißer Strahl" }
entries[36879] = { ["name"] = "Wasser herbeizaubern", ["text"] = "885 Mana\nWirken in 3 sek.\nZaubert ein erfrischendes Getränk herbei." }
entries[36880] = { ["name"] = "Arkane Intelligenz", ["text"] = "1850 Mana\nSofort\nErhöht 30 Min. lang die Intelligenz des Ziels um 100." }
entries[36881] = { ["name"] = "Eisrüstung", ["text"] = "630 Mana\nSofort\nErhöht die Rüstung um 2000 und den Frostwiderstand um 50. Wenn ein Feind den Zaubernden schlägt, kann 5 Sek. lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen seinen Angriffen um 0% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an." }
entries[36883] = { ["name"] = "Manadiamant herbeizaubern", ["text"] = "1670 Mana\nWirken in 3 sek.\nZaubert einen Manadiamanten herbei, der zum sofortigen Wiederherstellen von 10.000 Mana verwendet werden kann.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[36884] = { ["name"] = "Kettenblitzschlag", ["text"] = "100 Meter Reichweite\nSofort 6 sek. Abklingzeit\nKosmetische Version des skalierbaren Kettenblitzzaubers." }
entries[36885] = { ["name"] = "Bösen Geist der Blutschläger", ["text"] = "Unbegrenzte Reichweite\nSofort\nBeschwört im Umkreis von 5 Metern um den Zaubernden einen bösen Geist der Blutschläger." }
entries[36886] = { ["name"] = "Boshafter Furor", ["text"] = "Unbegrenzte Reichweite\nSofort\nErhöht den Betrag jeglicher erzeugten Bedrohung um 500%." }
entries[36887] = { ["name"] = "Ohrenbetäubendes Gebrüll", ["text"] = "Sofort\nFügt allen Gegnern im Umkreis von 45 Metern Schattenschaden zu. Zusätzlich werden sie 5 Sek. lang entwaffnet und zum Schweigen gebracht." }
entries[36888] = { ["name"] = "Wütender Geist der Arakkoa", ["text"] = "Sofort\nBeschwört 0 Kaliri der Lashh'an, um den Zaubernden bis zur Freigabe zu begleiten." }
entries[36889] = { ["name"] = "Transporterankunft" }
entries[36890] = { ["name"] = "Transporter von Area 52", ["text"] = "Wirken in 10 sek.\nZerreißt die Dimensionsschranken und transportiert Euch nach Area 52 im Nethersturm. Manchmal können technische Probleme auftreten, aber das ist ja das Spannende bei der Gobliningenieurskunst!" }
entries[36891] = { ["name"] = "Verwüsten", ["text"] = "8 Meter Reichweite\nSofort\nFügt dem Ziel 1665 bis 1935 Schaden zu, schleudert es in die Luft und trifft es erneut." }
