entries[36907] = { ["name"] = "Feuerschild", ["text"] = "210 Mana 30 Meter Reichweite\nSofort\nUmgibt das Ziel mit einem Schild aus Feuer. Der Feuerwiderstand des Ziels wird um 100 erhöht und jeder Schlag gegen das Ziel fügt dem Angreifer 50 Feuerschaden zu. Hält 3 Min. lang an. Der Zaubernde kann 'Feuerschild' nicht auf sich selbst wirken." }
entries[36908] = { ["name"] = "Raumkrümmung", ["text"] = "40 Meter Reichweite\nSofort\nTeleportiert den Zaubernden hinter das Ziel." }
